//! Known-answer tests for the solo-arx Feistel cipher, run by `cargo test`.
//!
//! Before this file the KAT files were checked only by the CI example
//! `examples/kat_verify.rs`, so `cargo test` could pass while the cipher's
//! output changed. These tests make a change in the output fail the test suite.
//!
//! Sources of the expected values:
//! * the four files under `docs/tables/` (generated by the implementation, and
//!   cross-checked by the independent Python reference
//!   `scripts/herringfish_ref.py`, which matches all 145 vectors);
//! * `ZERO_KEY_ROUND_KEYS` / `SEQ_KEY_ROUND_KEYS`, produced by that Python
//!   reference from the text of spec section 12-S, not by the Rust code.

use herringfish::cipher::arx_key_schedule::derive_round_keys;
use herringfish::cipher::feistel_arx::FeistelArx;
use std::path::Path;

struct Kat {
    rounds: usize,
    key: [u8; 32],
    pt: [u8; 16],
    ct: [u8; 16],
}

fn hex_bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

/// Parse the three KAT file styles used under docs/tables/.
fn parse(file: &str) -> Vec<Kat> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("docs/tables")
        .join(file);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));

    let (mut rounds, mut key, mut pt) = (16usize, None, None);
    let mut out = Vec::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        if let Some(v) = line.strip_prefix("[rounds=") {
            rounds = v.trim_end_matches(']').parse().unwrap();
            continue;
        }
        if line.starts_with('#') {
            // "# ... N rounds KAT" header style (kat_reduced_all.txt)
            if let Some(head) = line.strip_suffix(" rounds KAT") {
                let digits: String = head
                    .chars()
                    .rev()
                    .take_while(|c| c.is_ascii_digit())
                    .collect::<Vec<_>>()
                    .into_iter()
                    .rev()
                    .collect();
                rounds = digits.parse().unwrap();
            }
            continue;
        }
        let (field, value) = match line.split_once([':', '=']) {
            Some((f, v)) => (f.trim().to_ascii_lowercase(), v.trim()),
            None => continue,
        };
        match field.as_str() {
            "key" => key = Some(hex_bytes(value).try_into().unwrap()),
            "plaintext" => pt = Some(hex_bytes(value).try_into().unwrap()),
            "ciphertext" => out.push(Kat {
                rounds,
                key: key.expect("ciphertext before key"),
                pt: pt.expect("ciphertext before plaintext"),
                ct: hex_bytes(value).try_into().unwrap(),
            }),
            _ => {}
        }
    }
    out
}

fn check_file(file: &str, expected_vectors: usize) {
    let kats = parse(file);
    // A parser that silently finds nothing must fail, not pass vacuously.
    assert_eq!(
        kats.len(),
        expected_vectors,
        "{file}: unexpected vector count"
    );
    for (n, k) in kats.iter().enumerate() {
        let mut block = k.pt;
        FeistelArx::new_with_rounds(&k.key, k.rounds).encrypt_block(&mut block);
        assert_eq!(
            block, k.ct,
            "{file} vector {n} (rounds={}): ciphertext mismatch",
            k.rounds
        );

        FeistelArx::new_with_rounds(&k.key, k.rounds).decrypt_block(&mut block);
        assert_eq!(block, k.pt, "{file} vector {n}: decrypt does not invert");
    }
}

#[test]
fn kat_vectors_v02_full_16_rounds() {
    check_file("kat_vectors_v02.txt", 9);
}

#[test]
fn kat_reduced_rounds_v02() {
    check_file("kat_reduced_rounds_v02.txt", 9);
}

#[test]
fn kat_reduced_all() {
    check_file("kat_reduced_all.txt", 27);
}

#[test]
fn kat_expanded_v02() {
    check_file("kat_expanded_v02.txt", 100);
}

/// Round keys from the independent Python reference (spec section 12-S).
#[rustfmt::skip]
const ZERO_KEY_ROUND_KEYS: [u64; 16] = [
    0xd3dca170e709b4d3, 0x472e4665656e9df8,
    0x44d96b170b5a8fe5, 0x7d8fd97cc43e1cb3,
    0x6d05021dd7960341, 0xad6950c0bd39fbbe,
    0xb0d26f38610c50a2, 0xd7167949b6612d9f,
    0x58f4bc96cc73f49c, 0x096996e75337e1c0,
    0xc36ac92e9b56309f, 0x5738ca8363400065,
    0x752c500551ac533e, 0x5a920244127bc647,
    0x8f739ed61a442142, 0x29df013015154b68,
];

#[rustfmt::skip]
const SEQ_KEY_ROUND_KEYS: [u64; 16] = [
    0xcd08e22640611d4e, 0xe354d10f92c540f5,
    0xfe18893fa1725dc2, 0xe49ae20a79b1a930,
    0x5876ae21ccc962f5, 0xbc685bfb7e259d2e,
    0xe894f873cf7546b1, 0x38d75090a6475976,
    0xec2263df851402b7, 0x92b518151aa3a247,
    0xdfbb1dcb2505f9c9, 0x53a56290c705b01d,
    0x0dcb22c6c8cec08f, 0x7741c4ad7c1bde5f,
    0x2b88042a9d8abf09, 0x35684dfe440a7425,
];

#[test]
fn round_keys_match_independent_reference() {
    let zero = [0u8; 32];
    assert_eq!(derive_round_keys(&zero, 16), ZERO_KEY_ROUND_KEYS);

    let mut seq = [0u8; 32];
    for (i, b) in seq.iter_mut().enumerate() {
        *b = i as u8;
    }
    assert_eq!(derive_round_keys(&seq, 16), SEQ_KEY_ROUND_KEYS);

    // The cipher must use exactly this schedule.
    assert_eq!(FeistelArx::new(&zero).round_keys(), ZERO_KEY_ROUND_KEYS);
}
